import { Controller } from "@hotwired/stimulus"
import { FetchRequest } from "@rails/request.js"

// Moves cards between columns (or statuses) by dragging them around the board.
// Columns keep their own order, so a dropped card simply joins its new column: the
// move is applied to the DOM right away and saved in the background. Asking for a
// JSON response keeps the save from answering with a Turbo Stream, and the board's
// refresh broadcast skips the client that made the change — the board stays exactly
// as the drop left it.
